import {earlierCollegeExploration} from './career-exploration-ui.js';
import {expandedCareerPanel} from './expanded-top-ui.js';
import {matchPresentation} from './match-presentation.js';
import {pendingProfessionPanel,careerComparisonsPanel} from './career-comparisons-ui.js';
import {careerCheckSpec} from './career-check-questions.js';
import {clinicalTrainingTimeline} from './education-evidence-ui.js';
import {planMatchCandidates} from './plan-matches.js';
import {studyCostSummary} from './study-cost-summary.js';
import {careerTitle,careerEducationSummary,careerEducationBullets,collegeBenefit} from './career-presentation.js';
import {careerInsights} from './career-insights.js';
import {careerGlyph} from './career-glyph.js';
import {careerLanguage} from './career-language.js';
import {educationBadges} from './career-opportunities-ui.js';
import {educationRouteGroups,educationRoutesFor} from './education-routes.js';
import {collegeProgramOptions} from './college-program-options.js';
import {salaryProgression,formatSalary} from './salary-progression.js';
import {salaryPreviewInputs} from './guide-state.js';
import {calculateLifestyle} from './lifestyle.js';
import {lifestyleIncomeRange} from './lifestyle-story.js';
import {careerFundingPanel,careerScenario} from './financial-scenario-ui.js';
import {occupationById} from './occupation-data.js';
import {escapeHTML as h} from './html.js';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const more=(title,html)=>'<details class="more-info"><summary>'+h(title)+'</summary>'+html+'</details>';
const jump=(id,text)=>'<a href="#'+h(id)+'" data-scroll-to="'+h(id)+'">'+h(text)+'</a>';
function whyMatch(s,row){const used=new Set(),reasons=row.evidence?row.evidence.filter(e=>{if(used.has(e.questionId))return false;used.add(e.questionId);return true;}).slice(0,3).map(e=>e.text):[...new Set(row.reasons||[])].slice(0,3),op=row.opportunity;
 const lead=row.kind==='related'?(op?.connection||'Your interests connect with this related work.'):row.kind==='chosen'?'You chose this career to explore.':row.basis==='tasks'?'You liked several different parts of this work.':'Your interest profile and work choices connect with this career.';
 return '<section class="match-reasons"><h3>Why this matches you</h3><p><span class="match-rating rating-'+row.kind+'">'+h(row.rating)+'</span></p><p>'+h(lead)+'</p>'+(reasons.length&&(row.kind!=='related'||row.taskLedRelated)?'<ul>'+reasons.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul>':'')+(row.interestContrast?'<p class="match-note">Your task choices fit better than your wider interest pattern.</p>':'')+'</section>';
}
function workPreferences(s,o){const x=careerInsights(s,o),copy=[...x.connections.slice(0,1),...x.tradeoffs.slice(0,1),...x.next.slice(0,3)];return copy.length?'<section class="career-insights"><h3>How you like to work</h3>'+copy.map(t=>'<p>'+h(t)+'</p>').join('')+'</section>':'';}
function collegeBenefitShort(o){const v=collegeBenefit(o),copy=v.copy.split(/(?<=[.!?])\s+/).filter(t=>!/(?:not replace|not usually needed|still required|still come first|hiring and promotion rules depend)/i.test(t)).join(' ');return copy?'<aside class="college-benefit"><h3>'+h(v.title)+'</h3><p>'+h(copy)+'</p></aside>':'';}
function programsFor(o){
 if(o.id==='hairdresser')return [{id:'aveda-austin',title:'Cosmetology',school:'Aveda Arts Austin',award:'Cosmetology training',duration:'1,000 hours · about 9 months',benefit:'Learn hair, skin, nails, sanitation and safety.',url:'https://avedaarts.edu/campus/tx/austin/'}];
 if(o.id==='industrial-design')return [{id:'uh-industrial-design',title:'Industrial Design',school:'University of Houston',award:'Bachelor of Science',duration:'4 years · 132 credits',benefit:'Learn sketching, product design, model-making and user research.',url:'https://www.uh.edu/architecture/industrial-design/degree-programs/bsid/'}];
 const route=educationRoutesFor(o)[0]?.key,all=collegeProgramOptions(o.id).categories.flatMap(c=>c.options);
 if(route==='work'||route==='apprenticeship')return [];
 return all.filter(p=>route==='graduate'?['professional','bachelor','transfer'].includes(p.routeType):route==='college'?['bachelor','transfer'].includes(p.routeType):['workforce','bachelor'].includes(p.routeType)).slice(0,2);
}
function programsPanel(o){const ps=programsFor(o);if(!ps.length)return '';return '<section class="match-programs"><h3>Programs to explore</h3>'+ps.map(p=>'<article><h4><a href="'+h(p.url)+'" target="_blank" rel="noopener">'+h(p.title)+' ↗</a></h4><p><strong>'+h(p.school)+'</strong>'+ (p.award?' · '+h(p.award):'')+'</p>'+(p.duration?'<p>'+h(p.duration.replace(/;.*$/,'').replace(/^Published /,'').replace(/plan.*/,'plan'))+'</p>':'')+'<p>'+h((p.benefit||'').replace(/;.*$/,'').replace(/after checking.*$/,'').replace(/Explore this named advanced program.*/,'Continue with specialist study and supervised practice.'))+'</p></article>').join('')+'</section>';}
function costPanel(id){const b=studyCostSummary(id);return '<section class="match-costs" data-career-cost="'+h(id)+'"><h3>What training could cost</h3><p>'+h(b.example)+'</p><p>'+h(b.duration)+' · before aid</p><dl>'+b.rows.map(r=>'<div><dt>'+h(r.label)+'</dt><dd>'+money(r.amount)+'</dd></div>').join('')+'<div class="study-cost-total"><dt>Estimated total</dt><dd>'+money(b.rows.reduce((n,r)=>n+Math.round(r.amount),0))+'</dd></div></dl>'+more('What these costs include',b.parts.map(p=>'<p><strong>'+h(p.label)+' · '+money(p.amount)+'</strong></p><p>'+h(p.scope.replace(/Confirmed grants, funding, and personal contributions are entered below\./,'')).replace(/not a[^.]*\./gi,'')+'</p>').join('')+(b.sources.length?'<p>'+b.sources.slice(0,3).map((u,i)=>'<a href="'+h(u)+'" target="_blank" rel="noopener">Cost source '+(i+1)+' ↗</a>').join(' · ')+'</p>':''))+'</section>';}
function payPanel(id){const p=salaryProgression(id);return '<section class="match-pay"><h3>Estimated yearly pay</h3><p>Before tax · Austin area</p>'+(p.paidTraining?'<p class="paid-training-line"><strong>'+h(p.paidTraining.label)+' · '+formatSalary(p.paidTraining.amount)+'</strong></p>':'')+'<div class="match-pay-timeline">'+p.stages.map(x=>'<article><span>'+h(x.label)+'</span><strong>'+formatSalary(x.amount)+'</strong></article>').join('')+'</div>'+more('Pay sources','<p>'+h(p.geography)+' · '+h(p.referencePeriod)+'</p><p>Entry pay uses the local wage reference. The 5-, 10- and 20-year amounts are modeled from local wages.</p>'+(p.paidTraining?'<p><a href="'+h(p.paidTraining.sourceURL)+'" target="_blank" rel="noopener">Training pay source ↗</a></p>':'')+'<ul>'+p.sources.slice(0,3).map(x=>'<li><a href="'+h(x.url)+'" target="_blank" rel="noopener">'+h(x.title||x.publisher)+' ↗</a></li>').join('')+'</ul>')+'</section>';}
function lifestylePanel(s,id,{standalone=false}={}){if(!s.guide.lifestylePreset&&!s.guide.salaryPicked)return '<p><a href="#/journey/lifestyle">Set your lifestyle preferences →</a></p>';const p=salaryProgression(id),stage=p.paidTraining?.stageKey||'entry',input=salaryPreviewInputs(s,id,stage),r=input?calculateLifestyle(input):null;if(r?.status!=='illustration')return '';const gap=r.remaining,room=gap>=0&&gap/r.takeHome>=.1,key=gap<0?'short':room?'yes':'tight',title=gap<0?'This pay does not cover your lifestyle.':room?'This pay covers your lifestyle.':'This pay just covers your lifestyle.';return '<section class="match-lifestyle lifestyle-'+key+'"><h3>'+title+'</h3><p>'+h(p.paidTraining?p.paidTraining.label:'Starting pay')+' · '+formatSalary(Number(input.gross))+' / year before tax</p><p>'+(gap<0?'Choose a profession with higher income or adjust your lifestyle preferences.':room?'Your costs and savings fit, with room left over.':'Your costs and savings fit, with little left over.')+'</p>'+(gap<0?(standalone?'<a href="#/plan">Explore related matches that could cover your lifestyle →</a>':jump('other-matches','Explore related matches that could cover your lifestyle →')):'')+'</section>';}
export function resultCareerPanel(s,row,{prefix='match',choose=false,standalone=false}={}){const o=row.o;if(o.expandedDegree)return expandedCareerPanel(s,row,{choose:choose||s.guide.primaryCareer!==o.id});return '<div class="result-career-content" data-result-career="'+h(o.id)+'">'+educationBadges(o)+'<div class="career-work-line">'+(careerLanguage[o.id]||[o.summary]).slice(0,2).map(t=>'<p>'+h(t)+'</p>').join('')+'</div>'+whyMatch(s,row)+workPreferences(s,o)+'<section class="match-training"><h3>How to get there</h3>'+(salaryProgression(o.id)?.entryContext?'<p>'+h(salaryProgression(o.id).entryContext)+'</p>':'')+'<p><strong>'+h(careerEducationSummary(o))+'</strong></p><ul>'+careerEducationBullets(o).filter(t=>t!==careerEducationSummary(o)).slice(0,3).map(t=>'<li>'+h(t)+'</li>').join('')+'</ul>'+clinicalTrainingTimeline(o.id)+collegeBenefitShort(o)+programsPanel(o)+costPanel(o.id)+'</section>'+(row.kind==='related'&&careerCheckSpec(o.id)?'<p><a class="button secondary" href="#/journey/check-career/'+h(o.id)+'/0">Compare this profession with my interests →</a></p>':'')+payPanel(o.id)+lifestylePanel(s,o.id,{standalone})+(choose||s.guide.primaryCareer!==o.id?'<button class="button" data-action="journey-plan" data-id="'+h(o.id)+'">Choose this career →</button>':'')+'</div>';}
export const careerAccordion=(s,row,other=false)=>'<details class="result-career '+(other?'other-career':'top-career')+'" id="plan-match-'+h(row.id)+'"><summary><span>'+h(careerTitle(row.o))+'</span>'+(other?'<span class="match-rating rating-'+row.kind+'">'+h(row.rating)+'</span><span class="other-match-reason">'+h((row.opportunity?.connection||row.reasons?.[0]||'Your work interests connect with this career.').split(/(?<=[.!?])\s+/)[0].replaceAll('applied arts and design','hands-on design').replaceAll('visual arts','visual ideas').replaceAll('mathematics/statistics','math and data').replaceAll('information technology','technology'))+'</span>':'')+'</summary>'+resultCareerPanel(s,row)+'</details>';
function routeComparisons(data){const rows=data.all.filter(r=>r.opportunity?.meetsAtStart&&!r.opportunity.requiresExperience);return '<section class="education-match-comparison"><h2>Matches by education</h2><p>These potential matches could sustain your preferred lifestyle. Click each to explore.</p>'+educationRouteGroups.map(g=>{const choices=rows.filter(r=>educationRoutesFor(r.o).some(x=>x.key===g.id)).slice(0,5);const visible=new Set([...data.top,...data.other.slice(0,6)].map(r=>r.id));return '<div class="education-match-group"><h3>'+h(g.title)+'</h3>'+(choices.length?'<ul>'+choices.map(r=>'<li>'+(visible.has(r.id)?jump('plan-match-'+r.id,careerTitle(r.o)):'<a href="#/journey/profession/'+h(r.id)+'">'+h(careerTitle(r.o))+'</a>')+'</li>').join('')+'</ul>':'<p>No match</p>')+'</div>';}).join('')+'</section>';}
function savedWork(s){const actions=(s.actions||[]).filter(a=>!a.id.startsWith('explore-')),current=actions.filter(a=>a.careerId===s.guide.primaryCareer),earlier=actions.filter(a=>a.careerId!==s.guide.primaryCareer);const card=a=>'<article class="personal-action"><label><input type="checkbox" data-action-check="'+h(a.id)+'"'+(a.done?' checked':'')+'><strong>'+h(a.title)+'</strong></label><p>'+h(a.detail)+'</p><label for="plan-notice-'+h(a.id)+'">My notes</label><textarea id="plan-notice-'+h(a.id)+'" data-plan-action="'+h(a.id)+'" data-plan-field="notice" maxlength="2000">'+h(a.notice||'')+'</textarea></article>';return '<section id="plan-next" class="plan-saved-work">'+more('My saved notes and steps',current.length?current.map(card).join(''):'<p>Choose three starting actions for this career when you are ready.</p>')+(earlier.length?more('Earlier career steps & other saved work',earlier.map(card).join('')):'')+'</section>';}

export function resultsPlanPage(s,{historyHTML=''}={}){const data=planMatchCandidates(s),range=s.guide.lifestylePreset?lifestyleIncomeRange(s.finance.lifestyle):null;return '<div class="results-plan"><header class="results-plan-intro"><h1>'+(s.profile.nickname?h(s.profile.nickname)+'’s matches':'Your career matches')+'</h1><p>Open a career to see why it fits and what life could look like.</p></header>'+(range?'<aside class="guide-goal-strip"><strong>Your Austin lifestyle · '+formatSalary(range.low)+'–'+formatSalary(range.high)+' / year before tax</strong><a href="#/journey/lifestyle-summary">Review my lifestyle preferences →</a></aside>':'')+earlierCollegeExploration(s)+careerComparisonsPanel(s)+'<section id="plan-work" class="top-matches"><h2 id="first-matches">'+h(matchPresentation(s).label)+'</h2><p>'+h(matchPresentation(s).explanation)+'</p>'+(data.top.length?data.top.map(r=>careerAccordion(s,r)).join(''):'<p>Choose a field to explore, then answer its work questions.</p><a href="#/journey/pathways">Explore fields →</a>')+'</section>'+pendingProfessionPanel(s)+'<section id="other-matches" class="other-matches"><h2>Other matches</h2>'+(data.other.length?data.other.slice(0,6).map(r=>careerAccordion(s,r,true)).join(''):'<p>No other close match in this field.</p>')+'</section>'+routeComparisons(data)+savedWork(s)+(historyHTML?more('Earlier interests and activity notes',historyHTML):'')+'<section class="results-plan-tools">'+(s.guide.primaryCareer&&!occupationById(s.guide.primaryCareer)?.expandedDegree?'<a href="#/education-funding/'+h(s.guide.primaryCareer)+'">Plan grants, savings and loans →</a>':'')+'<button class="text-link" data-action="print">Print / save PDF</button><button class="text-link" data-action="guide-export">Export My Plan</button></section></div>';}
export function educationFundingPage(s,id){const o=occupationById(id);if(!o)return '<a href="#/plan">Back to matches →</a>';const draft=structuredClone(s);initializeFundingReference(draft,id);return '<div class="education-funding-page"><a href="#/plan">← Back to matches</a><h1>How to pay for '+h(careerTitle(o).toLowerCase())+' training</h1>'+careerFundingPanel(draft,id,{reference:studyCostSummary(id)})+'</div>';}

export function resultCareerPage(s,id){const data=planMatchCandidates(s),row=data.all.find(r=>r.id===id)||{id,o:occupationById(id),kind:'chosen',rating:'Your choice',reasons:[]};if(!row.o)return '<a href="#/plan">Back to matches →</a>';return '<div class="results-plan single-result"><a href="#/journey/professions">← Job matches</a><h1>'+h(careerTitle(row.o))+'</h1>'+resultCareerPanel(s,row,{choose:true,standalone:true})+'</div>';}

export function initializeFundingReference(s,id){if(!occupationById(id)||s.finance.careerScenarios?.[id]?.cost)return;const b=studyCostSummary(id);s.finance.careerScenarios??={};s.finance.careerScenarios[id]={...careerScenario(s,id),cost:String(Math.round(b.cost)),studyYears:String(b.years)};}
